"""Build one-sequence-at-a-time report from preserved evidence, no model calls."""
import html, json, pathlib, shutil
ROOT=pathlib.Path(__file__).resolve().parent
OUT=ROOT/"out"
evidence=json.loads((ROOT/"evidence.json").read_text())
manifest=json.loads((OUT/"manifest.json").read_text())
roles=["novice","information","causality","audio","picture"]
accounts={role:json.loads((OUT/"judgments"/f"{role}-account.json").read_text()) for role in roles}
raw=[json.loads(p.read_text()) for p in (OUT/"judgments").glob("*.json") if not p.name.endswith("-account.json")]
cost=sum((r.get("usage") or {}).get("cost",0) or 0 for r in raw)
assert abs(cost-evidence["cost_usd"])<1e-8
assert all(len(accounts[r]["clips"])==8 for r in roles[:3])
assert all(len(accounts[r]["clips"])==2 for r in roles[3:])
for c in manifest["clips"]:
 probe=json.loads((OUT/c["id"]/"ffprobe.json").read_text())
 v=next(s for s in probe["streams"] if s["codec_type"]=="video")
 assert (v["width"],v["height"])==(c["width"],c["height"])
 assert any(s["codec_type"]=="audio" for s in probe["streams"])
 assert float(probe["format"]["duration"])<=60.2
 assert not c["errors"]
for role in roles:
 r=json.loads((OUT/"judgments"/f"{role}.json").read_text())
 assert r["choices"][0]["finish_reason"]=="stop"
 assert r.get("provider")=="Google"
static=sorted((ROOT/"snapshot/qa/reports").glob("20*/summary.txt"))[-1]
(OUT/"qa-static-summary.txt").write_text(static.read_text())
shutil.copytree(static.parent,OUT/"qa-static",dirs_exist_ok=True)
validation={"revision":evidence["revision"],"eight_native_resolution_clips":True,"all_clips_have_non_silent_audio":True,"all_clips_under_60_seconds":True,"three_complete_independent_role_passes":True,"two_audio_and_two_picture_ablations":True,"zdr_required_in_all_requests":True,"cost_usd":cost,"within_2_usd":cost<=2,"browser_page_errors":0,"static_qa":"fail: source WAVs absent from git archive; 65 cue metadata omissions","limitations":["autopilot active median 49.18 ticks/s, slower than nominal 60, never accelerated", "full simultaneous radio-box + player-hit overlap not obtained", "same model, not model consensus or human usability test", "G subtitle leakage and other observer errors retained"]}
(OUT/"validation.json").write_text(json.dumps(validation,indent=2))
payload=json.dumps({"evidence":evidence,"manifest":manifest,"accounts":accounts},ensure_ascii=False).replace("</","<\\/")
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Neon Warden: intelligibility evidence</title><style>
:root{font:16px/1.5 system-ui;color:#e9eef5;background:#10141b}body{max-width:1040px;margin:auto;padding:24px}h1{font-size:1.65rem}h2{font-size:1.2rem}button,select{font:inherit;color:inherit;background:#253247;border:1px solid #72839a;border-radius:5px;padding:7px;margin:4px 4px 4px 0;cursor:pointer}button:focus-visible,select:focus-visible{outline:3px solid #68d1f7}a{color:#81d8ff}video{display:block;max-width:100%;max-height:600px;margin:12px auto;background:black}article,details{background:#1a2330;padding:16px;margin:16px 0;border-radius:8px}.muted{color:#b5c1d1}.warning{color:#ffcf81}td,th{padding:8px;text-align:left;vertical-align:top;border-bottom:1px solid #3f4c5d}table{border-collapse:collapse;min-width:560px;width:100%}.scroll{overflow-x:auto}pre{white-space:pre-wrap;font-size:.85rem}#controls{display:flex;flex-wrap:wrap;align-items:center;gap:4px}#evidence article{background:#223044}code{overflow-wrap:anywhere}summary{cursor:pointer;font-weight:600}ol{padding-left:24px}@media(max-width:500px){body{padding:12px}video{max-height:540px}}
</style><body><h1>What can a first-time observer actually understand?</h1><p>Eight real-time recordings, three independent judging passes, one model. No beauty score.</p><p class="muted">Frozen revision <code>85ee1114a2177cdf20faf85edeefc7821b3d6bee</code>. OpenRouter $0.548716, enforced ZDR. <a href="README.md">Methods, findings and limitations</a>.</p><p class="warning">AI observers are not human usability participants. Some confident accounts are wrong. The hit clip lacks the requested simultaneous visible radio box; coverage is partial.</p>
<div id="controls"><label>Sequence <select id="sequence"></select></label><button id="prev">Previous</button><button id="next">Next</button><select id="mode" aria-label="Signal mode"><option value="clip">Sound + picture</option><option value="audio">Sound only</option><option value="picture">Picture only</option></select><button id="native">Fullscreen video</button></div>
<p id="metadata" class="muted"></p><video id="video" controls preload="metadata" playsinline></video><p>Watch once at normal speed before revealing notes. The player is a recording: no controls or input log are supplied to observers. The video may be scaled to fit this page; fullscreen for larger viewing.</p><button id="reveal">Reveal ground truth and observer accounts</button><section id="notes" hidden><h2 id="name"></h2><div id="evidence"></div><details><summary>Independent ratings and raw accounts (not averaged)</summary><p class="warning">G hearing claims fail the silent-correction canary. D and E cause ratings conflict with missed ground-truth events. Do not read these as validated success scores.</p><div id="ratings" class="scroll"></div><div id="raw"></div></details></section>
<details><summary>Five changes, ranked before more VFX</summary><ol id="fixes"></ol></details><details><summary>Proposed attention budget, with evidence</summary><p><b>One urgent threat cue:</b> reserve survival space for impending impact or damage; E lost all three lives without observers reconstructing the sequence. Do not let install controls compete with hull state.</p><p><b>One action confirmation:</b> consolidate lock/intel/part-break outcomes into a short causal receipt; C's lock-to-kill transition is about 0.18 s, and D's two real pod breaks were missed.</p><p><b>One main speech owner:</b> prioritize the current required instruction or salient character line. C's audio-only pass confirms speech masking independently of subtitles. Defer or cancel lower-priority speech rather than making every channel louder.</p><p><b>Deferred lore and toasts:</b> silently file nonurgent codex/radio detail for a safe interval or pause. F's calm inspector reads well; gameplay's four reading zones do not. This is a testable starting budget, not a universal numeric law.</p></details><p><a href="out/manifest.json">Event timeline</a> · <a href="evidence.json">Evidence table JSON</a> · <a href="out/validation.json">Validation</a> · <a href="out/qa-static-summary.txt">Frozen-source static QA</a></p>
<script>const data=PAYLOAD;const $=id=>document.getElementById(id);const names={A:'Quiet combat',B:'Dense combat, Chromebook-sized viewport',C:'Scan, lock, Writ and competing speech',D:'Boss pod breaks and core exposure',E:'Damage, codex and failure',F:'Calm hangar reading',G:'Wrong input and fresh focus',H:'Narrow hangar layout'};let id='A';
for(const c of data.manifest.clips){const o=document.createElement('option');o.value=c.id;o.textContent=c.id;$('sequence').append(o)}
function text(tag,value,parent){const e=document.createElement(tag);e.textContent=value;parent.append(e);return e}
function seek(t){$('video').currentTime=Math.max(0,t-1);$('video').play()}
function load(){id=$('sequence').value;const c=data.manifest.clips.find(x=>x.id===id);for(const o of $('mode').options)o.disabled=o.value!=='clip'&&!['C','G'].includes(id);if($('mode').selectedOptions[0].disabled)$('mode').value='clip';$('video').pause();$('video').src='out/'+id+'/'+$('mode').value+'.mp4';$('video').playbackRate=1;$('metadata').textContent=id+' · '+c.width+'×'+c.height+' · '+c.duration_s+' s · 1× playback';$('notes').hidden=true;$('reveal').hidden=false;$('name').textContent=names[id];$('evidence').replaceChildren();
for(const row of data.evidence.rows.filter(r=>r.clip===id)){const a=document.createElement('article');const b=text('button',row.at_s.toFixed(2)+' s: play from here',a);b.onclick=()=>seek(row.at_s);for(const [label,key] of [['Ground truth','ground_truth'],['Independent accounts','accounts'],['Missed or confused','confusion'],['Minimal fix','minimal_fix']]){text('b',label+': ',a);text('p',row[key],a)}$('evidence').append(a)}
$('ratings').replaceChildren();const table=document.createElement('table');const head=text('tr','',table);for(const s of ['Pass','Detection','Cause','Text','Audio source','Recovery'])text('th',s,head);$('raw').replaceChildren();for(const role of ['novice','information','causality','audio','picture']){const result=data.accounts[role].clips.find(c=>c.id===id);if(!result)continue;const tr=text('tr','',table);text('td',role,tr);for(const key of ['detection','cause_attribution','text_legibility','audio_source_identification','recoverability'])text('td',result.ratings[key]??'n/a',tr);const details=text('details','',$('raw'));text('summary',role+' account',details);text('pre',JSON.stringify(result,null,2),details)}$('ratings').append(table)}
$('sequence').onchange=load;$('mode').onchange=load;$('prev').onclick=()=>{$('sequence').selectedIndex=($('sequence').selectedIndex+7)%8;load()};$('next').onclick=()=>{$('sequence').selectedIndex=($('sequence').selectedIndex+1)%8;load()};$('reveal').onclick=()=>{$('notes').hidden=false;$('reveal').hidden=true};$('native').onclick=()=>{$('video').requestFullscreen?.()};for(const f of data.evidence.fixes){const li=text('li','',$('fixes'));text('b',f.title,li);text('p',f.proposal,li);text('p',f.why,li)}load();</script></body></html>'''.replace('PAYLOAD',payload)
(ROOT/"index.html").write_text(page)
print(f"PASS: 8 native AV clips, 24 role accounts, 4 ablation accounts, cost ${cost:.6f}; HTML and evidence validated. Frozen static QA fails retained separately.")
